const q = $json.query || {};

if (!q.ctx) {
  throw new Error('Missing ctx in decision link');
}

let ctx;
try {
  ctx = JSON.parse(decodeURIComponent(q.ctx));
} catch (e) {
  throw new Error('Invalid ctx payload');
}

const decision = String(q.decision || '').toLowerCase();
if (!['approved', 'rejected'].includes(decision)) {
  throw new Error('Invalid decision');
}

const rowNumber = Number(ctx.rowNumber);
if (!rowNumber || isNaN(rowNumber)) {
  throw new Error('Missing or invalid rowNumber in ctx');
}

return [{
  json: {
    decision,
    team: String(ctx.team || ''),
    rowNumber,
    requesterEmail: String(ctx.requesterEmail || ''),
    requesterName: String(ctx.requesterName || ''),
    dept: String(ctx.dept || ''),
    material: String(ctx.material || ''),
    itemDetail: String(ctx.itemDetail || ''),
    category: String(ctx.category || ''),
    purpose: String(ctx.purpose || ''),
    requirementDate: String(ctx.requirementDate || ''),
    qty: String(ctx.qty || ''),
    unitPrice: String(ctx.unitPrice || '')
  }
}];

const rowNumber = $('Decode Decision Link').item.json.rowNumber;
const match = items.find(i => Number(i.json.row_number) === Number(rowNumber));

if (!match) {
  throw new Error('Row not found in Purchase sheet: ' + rowNumber);
}

const currentStatus = String(match.json['Management Review'] || '').trim();

return [{
  json: {
    ...$('Decode Decision Link').item.json,
    alreadyDecided: currentStatus.length > 0,
    currentStatus
  }
}];

const body = $json.body || {};
const name = String(body.name || '').trim();
const requirementDate = String(body.requirementDate || '').trim();
const items = Array.isArray(body.items) ? body.items : [];

if (!name) throw new Error('Missing requester name');
if (!requirementDate) throw new Error('Missing requirement date');
if (items.length === 0) throw new Error('At least one item is required');

// Safer unique batch id: time + ms + random
const now = new Date();
const rand = Math.random().toString(36).slice(2, 8).toUpperCase();
const batchId =
  'ENG-' +
  now.getFullYear() +
  String(now.getMonth() + 1).padStart(2, '0') +
  String(now.getDate()).padStart(2, '0') + '-' +
  String(now.getHours()).padStart(2, '0') +
  String(now.getMinutes()).padStart(2, '0') +
  String(now.getSeconds()).padStart(2, '0') + '-' +
  String(now.getMilliseconds()).padStart(3, '0') + '-' +
  rand;

const requestDate = new Date().toLocaleString('en-GB', { timeZone: 'Africa/Lagos' });

return items.map((it, index) => {
  const sku = String(it.sku || '').trim();
  const itemDetail = String(it.itemDetail || '').trim();
  const category = String(it.category || '').trim();
  const purpose = String(it.purpose || '').trim();
  const quantity = Number(it.quantity);
  const unitPriceRaw = it.unitPrice;

  if (!sku) throw new Error(`Item ${index + 1}: SKU is required`);
  if (!itemDetail) throw new Error(`Item ${index + 1}: item detail is required`);
  if (!category) throw new Error(`Item ${index + 1}: category is required`);
  if (!purpose) throw new Error(`Item ${index + 1}: purpose is required`);
  if (!Number.isFinite(quantity) || quantity <= 0) {
    throw new Error(`Item ${index + 1}: quantity must be greater than zero`);
  }

  let unitPrice = '';
  if (unitPriceRaw !== undefined && unitPriceRaw !== '') {
    const parsed = Number(unitPriceRaw);
    if (!Number.isFinite(parsed) || parsed < 0) {
      throw new Error(`Item ${index + 1}: unit price must be zero or more`);
    }
    unitPrice = parsed;
  }

  return {
    json: {
      batchId,                 // for workflow usage
      Remarks: batchId,        // for sheet echo-back lookup
      'Request Date': requestDate,
      'Requestor': name,
      'Department': 'Engineering',
      'Name of Material / Part': sku,
      'Item Detail (Specification & Brand)': itemDetail,
      'Purchase Category': category,
      'Purpose': purpose,
      'Requirement Date': requirementDate,
      'Quantity': quantity,
      'Unit Price': unitPrice,
      'Total Value': unitPrice === '' ? '' : quantity * unitPrice
    }
  };
});

