<script>
(function() {
  if (!window.__ITEMS__ || !window.__ITEMS__.length) return;

  const DECISION_URL = '[URL]';
  const items = window.__ITEMS__;
  const tbody = document.getElementById('itemsBody');
  const submitBtn = document.getElementById('submitBtn');
  const countNote = document.getElementById('countNote');
  const statusBox = document.getElementById('status');
  const reasonWrap = document.getElementById('reasonWrap');
  const reasonEl = document.getElementById('rejectionReason');

  function updateCount() {
    const decided = items.filter(it => it._decision).length;
    const rejected = items.filter(it => it._decision === 'rejected').length;
    countNote.textContent = decided + ' of ' + items.length + ' decided';
    submitBtn.disabled = decided < items.length;
    if (reasonWrap) reasonWrap.style.display = rejected > 0 ? 'block' : 'none';
  }

  items.forEach((it, idx) => {
    const tr = document.createElement('tr');
    tr.dataset.idx = idx;

    ['material','detail','purpose','qty'].forEach(k => {
      const td = document.createElement('td');
      td.textContent = it[k];
      tr.appendChild(td);
    });

    const tdDecision = document.createElement('td');
    tdDecision.className = 'decision-cell';

    ['approved','rejected'].forEach(val => {
      const label = document.createElement('label');
      const radio = document.createElement('input');
      radio.type = 'radio';
      radio.name = 'decision_' + idx;
      radio.value = val;
      radio.addEventListener('change', () => {
        it._decision = val;
        tr.className = val;
        updateCount();
      });
      label.appendChild(radio);
      label.appendChild(document.createTextNode(val === 'approved' ? 'Approve' : 'Reject'));
      tdDecision.appendChild(label);
    });

    tr.appendChild(tdDecision);
    tbody.appendChild(tr);
  });

  document.getElementById('approveAll').addEventListener('click', () => setAll('approved'));
  document.getElementById('rejectAll').addEventListener('click', () => setAll('rejected'));

  function setAll(val) {
    items.forEach((it, idx) => {
      it._decision = val;
      const tr = tbody.querySelector('tr[data-idx="' + idx + '"]');
      tr.className = val;
      const radio = tr.querySelector('input[value="' + val + '"]');
      if (radio) radio.checked = true;
    });
    updateCount();
  }

  updateCount();

  submitBtn.addEventListener('click', async () => {
    statusBox.className = 'status';
    submitBtn.disabled = true;
    submitBtn.textContent = 'Submitting...';

    const decisions = items.map(it => ({
      rowNumber: it.rowNumber,
      material: it.material,
      detail: it.detail,
      purpose: it.purpose,
      qty: it.qty,
      decision: it._decision
    }));

    const rejectedCount = decisions.filter(d => d.decision === 'rejected').length;
    const rejectionReason = reasonEl ? String(reasonEl.value || '').trim() : '';

    if (rejectedCount > 0 && !rejectionReason) {
      statusBox.className = 'status show err';
      statusBox.textContent = 'Please provide one rejection reason.';
      submitBtn.disabled = false;
      submitBtn.textContent = 'Submit Decisions';
      return;
    }

    try {
      const res = await fetch(DECISION_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          batchId: window.__BATCH_ID__,
          requesterEmail: window.__REQUESTER_EMAIL__,
          requesterName: window.__REQUESTER_NAME__,
          rejectionReason,
          decisions
        })
      });

      if (!res.ok) throw new Error('Server responded ' + res.status);

      statusBox.className = 'status show ok';
      statusBox.textContent = await res.text();
      submitBtn.textContent = 'Submitted';
    } catch (err) {
      statusBox.className = 'status show err';
      statusBox.textContent = 'Submission failed: ' + err.message;
      submitBtn.disabled = false;
      submitBtn.textContent = 'Submit Decisions';
    }
  });
})();
</script>
