  function levenshteinDistance(a, b) {
    const m = a.length, n = b.length;
    const dp = Array.from({ length: m + 1 }, () => new Array(n + 1).fill(0));
    for (let i = 0; i <= m; i++) dp[i][0] = i;
    for (let j = 0; j <= n; j++) dp[0][j] = j;
    for (let i = 1; i <= m; i++) {
      for (let j = 1; j <= n; j++) {
        if (a[i - 1] === b[j - 1]) dp[i][j] = dp[i - 1][j - 1];
        else dp[i][j] = 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
      }
    }
    return dp[m][n];
  }

  function findClosestSku(normInput) {
    let best = null, bestDist = Infinity;
    normalizedKeyList.forEach(k => {
      const d = levenshteinDistance(normInput, k);
      if (d < bestDist) { bestDist = d; best = k; }
    });
    if (best && bestDist > 0 && bestDist <= 2) return best;
    return null;
  }

  // --- Populate datalist for typing assistance ---
  skuCatalog.forEach(r => {
    const opt = document.createElement('option');
    opt.value = r.sku;
    skuOptions.appendChild(opt);
  });
  const otherOption = document.createElement('option');
  otherOption.value = 'Others';
  skuOptions.appendChild(otherOption);

  function addItem() {
    const frag = template.content.cloneNode(true);
    itemsWrap.appendChild(frag);
    const lastCard = itemsWrap.querySelector('.item-card:last-child');
    if (lastCard) applySkuBehavior(lastCard);
    renumber();
  }

  function renumber() {
    const cards = itemsWrap.querySelectorAll('.item-card');
    cards.forEach((card, i) => {
      card.querySelector('.item-index').textContent = 'ITEM ' + String(i + 1).padStart(2, '0');
      card.querySelector('.remove-item').style.display = cards.length > 1 ? 'block' : 'none';
    });
    countNote.textContent = cards.length + (cards.length === 1 ? ' item ready to submit' : ' items ready to submit');
  }

  function applySkuBehavior(card) {
    const skuEl = card.querySelector('.f-sku');
    const detailWrap = card.querySelector('.detail-wrap');
    const detailEl = card.querySelector('.f-detail');
    const detailNote = card.querySelector('.f-detail-note');
    const feedback = card.querySelector('.sku-feedback');

    function refresh() {
      const raw = skuEl.value || '';
      const norm = normalizeSku(raw);
      feedback.className = 'sku-feedback';
      feedback.innerHTML = '';

      if (!norm) {
        detailWrap.style.display = 'none';
        detailEl.value = '';
        detailEl.required = false;
        card.dataset.skuState = 'empty';
        return;
      }

      if (norm === 'OTHERS') {
        detailWrap.style.display = 'block';
        detailEl.value = '';
        detailEl.readOnly = false;
        detailEl.required = true;
        detailNote.textContent = 'Type a description for this new item.';
        card.dataset.skuState = 'others';
        return;
      }

      if (Object.prototype.hasOwnProperty.call(normalizedBySku, norm)) {
        detailWrap.style.display = 'block';
        detailEl.value = normalizedBySku[norm];
        detailEl.readOnly = true;
        detailEl.required = false;
        detailNote.textContent = 'Auto-filled from table_3 Confirm this matches what you need.';
        card.dataset.skuState = 'known';
        return;
      }

      // Unrecognized SKU
      detailWrap.style.display = 'none';
      detailEl.value = '';
      detailEl.required = false;
      card.dataset.skuState = 'invalid';

      const suggestion = findClosestSku(norm);
      feedback.classList.add('err');
      if (suggestion) {
        const span = document.createElement('span');
        span.appendChild(document.createTextNode('SKU not found in Plantilla Stock. Did you mean '));
        const link = document.createElement('span');
        link.className = 'suggest-link';
        link.textContent = suggestion;
        link.addEventListener('click', () => {
          skuEl.value = suggestion;
          refresh();
        });
        span.appendChild(link);
        span.appendChild(document.createTextNode('?'));
        feedback.appendChild(span);
      } else {
        feedback.textContent = 'SKU not found in Plantilla Stock. Confirm the SKU name or Type "Others" to add a new item.';
      }
    }

    skuEl.addEventListener('input', refresh);
    refresh();
  }

  itemsWrap.addEventListener('click', (e) => {
    if (e.target.classList.contains('remove-item')) {
      e.target.closest('.item-card').remove();
      renumber();
    }
  });

  document.getElementById('addItemBtn').addEventListener('click', addItem);
  addItem();

  function showStatus(kind, msg) {
    statusBox.className = 'status show ' + kind;
    statusBox.textContent = msg;
  }

  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    if (!form.reportValidity()) return;

    statusBox.className = 'status';

    const requirementDate = document.getElementById('reqDate').value;
    const cards = [...itemsWrap.querySelectorAll('.item-card')];

    for (const card of cards) {
      const state = card.dataset.skuState;

      if (state === 'invalid' || state === 'empty' || !state) {
        showStatus('err', 'One or more items has an invalid or missing SKU. Please fix highlighted fields before submitting.');
        card.querySelector('.f-sku').focus();
        return;
      }

      if (state === 'others') {
        const detail = (card.querySelector('.f-detail').value || '').trim();
        if (!detail) {
          showStatus('err', 'Please enter a description for items marked "Others".');
          card.querySelector('.f-detail').focus();
          return;
        }
      }
    }

    const items = cards.map(card => ({
      sku: card.querySelector('.f-sku').value.trim(),
      itemDetail: card.querySelector('.f-detail').value.trim(),
      category: card.querySelector('.f-category').value,
      purpose: card.querySelector('.f-purpose').value.trim(),
      quantity: card.querySelector('.f-qty').value,
      unitPrice: card.querySelector('.f-price').value
    }));

    const payload = {
      name: document.getElementById('name').value.trim(),
      requirementDate,
      items
    };

    submitBtn.disabled = true;
    submitBtn.textContent = 'Submitting...';

    try {
      const res = await fetch(WEBHOOK_URL, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });
      if (!res.ok) throw new Error('Server responded ' + res.status);

      const serverMsg = await res.text();
      showStatus('ok', serverMsg || ('Submitted - ' + items.length + ' item(s) sent for approval.'));
      form.reset();
      document.getElementById('name').value = 'Blessing';
      itemsWrap.innerHTML = '';
      addItem();
    } catch (err) {
      showStatus('err', 'Submission failed - please try again. (' + err.message + ')');
    } finally {
      submitBtn.disabled = false;
      submitBtn.textContent = 'Submit requisition';
    }
  });
</script>
</body>
</html>
`;

const htmlWithCatalog = html
  .replace('__SKU_CATALOG_JSON__', JSON.stringify(skuCatalog).replace(/</g, '\\u003c'))
  .replace('__SKU_BY_KEY_JSON__', JSON.stringify(skuByKey).replace(/</g, '\\u003c'));

return [{ json: { html: htmlWithCatalog } }];

const ctx = $('Prepare Batch Lookup').item.json || {};
const batchId = String(ctx.batchId || '').trim();
const rows = items || [];

if (!batchId) throw new Error('Missing batchId in lookup context');
if (!rows.length) throw new Error('No rows found in sheet for batch: ' + batchId);

const sorted = [...rows].sort((a, b) => Number(a.json.row_number) - Number(b.json.row_number));

const requesterName = String(ctx.requesterName || sorted[0].json['Requestor'] || '').trim();
const requirementDate = String(ctx.requirementDate || sorted[0].json['Requirement Date'] || '').trim();
const requesterEmail = '[EMAIL]';

const batchItems = sorted.map(r => ({
  rowNumber: Number(r.json.row_number),
  material: String(r.json['Name of Material / Part'] || ''),
  detail: String(r.json['Item Detail (Specification & Brand)'] || ''),
  category: String(r.json['Purchase Category'] || ''),
  purpose: String(r.json['Purpose'] || ''),
  qty: String(r.json['Quantity'] || ''),
  unitPrice: String(r.json['Unit Price'] || '')
}));

return [{
  json: {
    batchId,
    department: 'engineering',
    requesterName,
    requesterEmail,
    requirementDate,
    items: batchItems,
    itemsJson: JSON.stringify(batchItems),
    status: 'open',
    createdBy: requesterName,
    reviewUrl: '[URL]' + encodeURIComponent(batchId)
  }
}];

const purchaseRows = items;
const body = $('Engineering Decision Webhook.').item.json.body || {};
const batchRow = $('Get Approval Batch For Decision').item.json || {};

const batchId = String(body.batchId || '').trim();
const decisions = Array.isArray(body.decisions) ? body.decisions : [];
const rejectionReason = String(body.rejectionReason || '').trim();

const requesterEmail = String(batchRow.requester_email || '');
const requesterName = String(batchRow.requester_name || '');
const batchStatus = String(batchRow.status || '').trim().toLowerCase();

if (!batchId) {
  throw new Error('Missing batchId');
}
if (!batchRow.batch_id) {
  throw new Error('Approval batch not found');
}
if (batchStatus === 'processed') {
  throw new Error('This batch has already been processed');
}
if (decisions.length === 0) {
  throw new Error('No decisions submitted');
}

const hasRejected = decisions.some(
  d => String(d.decision || '').trim().toLowerCase() === 'rejected'
);

if (hasRejected && !rejectionReason) {
  throw new Error('Rejection reason is required when any item is rejected');
}

let allowedItems = [];
try {
  allowedItems = typeof batchRow.items_json === 'string'
    ? JSON.parse(batchRow.items_json)
    : batchRow.items_json;
} catch {
  throw new Error('Stored batch items are invalid');
}

const allowedRowNumbers = new Set(
  (allowedItems || [])
    .map(it => Number(it.rowNumber))
    .filter(n => Number.isFinite(n))
);

const seen = new Set();

return decisions.map((d, index) => {
  const rowNumber = Number(d.rowNumber);
  const decision = String(d.decision || '').trim().toLowerCase();

  if (!Number.isFinite(rowNumber)) {
    throw new Error(`Decision ${index + 1}: invalid row number`);
  }
  if (!allowedRowNumbers.has(rowNumber)) {
    throw new Error(`Decision ${index + 1}: row ${rowNumber} is not part of this batch`);
  }
  if (!['approved', 'rejected'].includes(decision)) {
    throw new Error(`Decision ${index + 1}: invalid decision`);
  }
  if (seen.has(rowNumber)) {
    throw new Error(`Decision ${index + 1}: duplicate row ${rowNumber}`);
  }
  seen.add(rowNumber);

  const row = purchaseRows.find(r => Number(r.json.row_number) === rowNumber);
  if (!row) {
    throw new Error(`Decision ${index + 1}: purchase row ${rowNumber} not found`);
  }

  const currentStatus = String(row.json['Management Review'] || '').trim();

  return {
    json: {
      batchId,
      rowNumber,
      material: String(d.material || ''),
      detail: String(d.detail || ''),
      purpose: String(d.purpose || ''),
      decision,
      requesterEmail,
      requesterName,
      alreadyDecided: currentStatus.length > 0,
      currentStatus,
      rejectionReason
    }
  };
});

const decided = $('Filter Not Yet Decided').all().map(i => i.json);

const approvedList = decided.filter(d => d.decision === 'approved');
const rejectedList = decided.filter(d => d.decision === 'rejected');

function renderApprovedList(list) {
  if (!list.length) return '<p>None</p>';
  return '<ul>' + list.map(item =>
    `<li><strong>${item.material || 'Unnamed item'}</strong> — ${item.detail || 'No description'} — Purpose: ${item.purpose || 'Not specified'} (Row ${item.rowNumber})</li>`
  ).join('') + '</ul>';
}

function renderRejectedList(list) {
  if (!list.length) return '<p>None</p>';
  return '<ul>' + list.map(item =>
    `<li><strong>${item.material || 'Unnamed item'}</strong> — ${item.detail || 'No description'} — Reason: ${item.rejectionReason || 'Not provided'} (Row ${item.rowNumber})</li>`
  ).join('') + '</ul>';
}

return [{
  json: {
    batchId: decided[0]?.batchId || '',
    approvedList,
    rejectedList,
    requesterEmail: decided[0]?.requesterEmail || '',
    requesterName: decided[0]?.requesterName || '',
    approvedHtml: renderApprovedList(approvedList),
    rejectedHtml: renderRejectedList(rejectedList)
  }
}];

