const row = items[0]?.json || {};
const batchId = String(
$('Engineering Checklist Webhook').item.json.query?.batchId ||
row.batch_id ||
''
).trim();

if (!batchId) {
return [{ json: { error: 'Approval link is invalid or missing batch ID.' } }];
}

if (!row.batch_id) {
return [{ json: { error: 'Approval batch was not found. Please request a new approval link.' } }];
}

if (String(row.status || '').trim().toLowerCase() === 'processed') {
const processedAt = row.processed_at
? new Date(row.processed_at).toLocaleString('en-GB', { timeZone: 'Africa/Lagos' })
: 'an earlier time';
return [{ json: { error: 'This approval batch was already processed on ' + processedAt + '.' } }];
}

let parsedItems = [];
try {
parsedItems = typeof row.items_json === 'string' ? JSON.parse(row.items_json) : row.items_json;
} catch {
return [{ json: { error: 'Stored batch data is invalid. Contact admin.' } }];
}

if (!Array.isArray(parsedItems) || parsedItems.length === 0) {
return [{ json: { error: 'No items were found in this approval batch.' } }];
}

return [{
json: {
batchId: row.batch_id,
department: row.department,
requesterName: String(row.requester_name || ''),
requesterEmail: String(row.requester_email || ''),
requirementDate: String(row.requirement_date || ''),
items: parsedItems
}
}];

const first = $('Split Items (Eng Intake)').all()[0]?.json || {};
if (!first.batchId) throw new Error('Missing batchId from table_7 split');

return [{
  json: {
    batchId: String(first.batchId),
    requesterName: String(first['Requestor'] || ''),
    requirementDate: String(first['Requirement Date'] || '')
  }
}];

const items = $('Build Batch Context').item.json.items || [];

return items
  .filter(i => Number.isFinite(Number(i.rowNumber)))
  .map(i => ({
    json: {
      row_number: Number(i.rowNumber),
      Remarks: ''
    }
  }));

const rows = items.map(i => i.json || {});

const catalog = rows
  .map(r => ({
    sku: String(r.SKU || '').trim(),
    description: String(r.DESCRIPTION || '').trim()
  }))
  .filter(x => x.sku.length > 0 && x.description.length > 0);

const bySku = {};
for (const row of catalog) {
  bySku[row.sku.toUpperCase()] = row.description;
}

return [{
  json: {
    catalog,
    bySku
  }
}];
